func main() {
	if len(os.Args) < 3 {
		fmt.Fprintf(os.Stderr, "usage: %s <save|get|delete> <base-url> [token]\n", os.Args[0])
		os.Exit(2)
	}

	action := os.Args[1]
	baseURL := os.Args[2]
	store := auth.NewStoreWithService("entire-cli-debug")

	switch action {
	case "save":
		if len(os.Args) < 4 {
			fmt.Fprintln(os.Stderr, "missing token")
			os.Exit(2)
		}
		if err := store.SaveToken(baseURL, os.Args[3]); err != nil {
			fmt.Fprintf(os.Stderr, "save error: %v\n", err)
