function formatCheckpointAnalysisResponse(analysis: AnalysisRow | null): Record<string, unknown> {
  if (!analysis) return { status: "not_available" }

  if (analysis.status === "complete" && analysis.analysis_json) {
    try {
      return {
        ...JSON.parse(analysis.analysis_json),
        status: "complete",
      }
    } catch {
      return { status: "failed", error: "Malformed analysis data" }
    }
  }

  return {
    status: analysis.status,
    error: analysis.status === "failed" ? "Analysis generation failed" : undefined,
  }
}

