function formatCheckpointAnalysisResponse(analysis: AnalysisRow | null): Record<string, unknown> {
  if (!analysis) return { status: "not_available" }

  if (analysis.status === "complete" && analysis.analysis_json) {
    try {
      return {
        ...JSON.parse(analysis.analysis_json),
        status: "complete",
      }
    } catch {
      return { status: "failed", error: "Malformed analysis data" }
    }
  }

  return {
    status: analysis.status,
    error: analysis.status === "failed" ? "Analysis generation failed" : undefined,
  }
}

repoRoutes.get("/:org/:repo/checkpoints/:checkpointId/analysis", requireAuth, async (c) => {
  const userId = c.get("userId")
  const org = c.req.param("org")
  const repo = c.req.param("repo")
  const checkpointId = c.req.param("checkpointId")
  const repoFullName = `${org}/${repo}`

  if (!isValidCheckpointId(checkpointId)) {
    return c.json({ error: "Invalid checkpoint ID format" }, 400)
  }

  const db = getDb(c.env)
  const [repoAccess, flagResult] = await Promise.all([
    checkRepoAccess(db, repoFullName, userId),
    requireAnalysisFlag(c.env, db, userId),
  ])
  if (repoAccess instanceof Response) return repoAccess
  if (!repoAccess) return c.json({ error: "Repository not found" }, 404)
  if (flagResult instanceof Response) return flagResult

  const analysis = await db.analyses.getByCheckpointId(repoAccess.id, checkpointId)
  return c.json(formatCheckpointAnalysisResponse(analysis))
})

userRoutes.post("/checkpoints/analyses/batch", requireAuth, async (c) => {
  const userId = c.get("userId")
  const db = getDb(c.env)

  const body = await c.req
    .json<{ checkpointIds?: string[]; repoFullName?: string }>()
    .catch(() => null)

