runsRoutes.use("*", requireAdmin)

const requireRunsFeature: MiddlewareHandler<{ Bindings: Env; Variables: Variables }> = async (
  c,
  next,
) => {
  if (!isSandboxRunsEnabled(c.env)) {
    return c.json({ error: "Sandbox runs are not configured" }, 503)
  }
  return next()
}

