const encoder = new TextEncoder()

function sseFrame(event: string, data: unknown, id?: string): Uint8Array {
  const lines = []
  if (id) {
    lines.push(`id: ${id}`)
  }
  lines.push(`event: ${event}`)
  lines.push(`data: ${JSON.stringify(data)}`)
  return encoder.encode(`${lines.join("\n")}\n\n`)
}

function pingFrame(): Uint8Array {
  return encoder.encode(`: ping ${Date.now()}\n\n`)
}

function getMissingAgentCredentialError(env: Env, agentId: string): string | null {
  const agent = AGENT_COMMANDS[agentId]
  if (!agent) {
    return `Unsupported agent: ${agentId}`
  }

  if (!agent.requires_api_key || !agent.api_key_env_var) {
    return null
  }

  if (env[agent.api_key_env_var as keyof Env]) {
    return null
  }

  return `Agent "${agentId}" requires ${agent.api_key_env_var} to be configured on the API server`
}

runsRoutes.post("/runs", async (c) => {
  const body = await c.req
    .json<{
      repoUrl?: string
      ref?: string
      agent?: string
      initialPrompt?: string
    }>()
    .catch(() => null)

  if (!body?.repoUrl) {
    return c.json({ error: "repoUrl is required" }, 400)
  }

  const db = getDb(c.env)
  const config = getSandboxProviderConfig(c.env)
  if (!config) {
    return c.json({ error: "Sandbox runs are not configured" }, 503)
  }
  const resolved = await resolveRepoRef(db, body.repoUrl, body.ref)
  if (!resolved) {
    return c.json({ error: "Repository not found" }, 404)
  }

  maxRequests: DISPATCH_RATE_LIMIT_MAX_REQUESTS,
  windowSeconds: DISPATCH_RATE_LIMIT_WINDOW_SECONDS,
  keyPrefix: DISPATCH_RATE_LIMIT_KEY_PREFIX,
})

dispatchRoutes.use("*", requireAuth)
dispatchRoutes.use("/users/me/dispatches", rateLimitDispatches)

async function requireDispatchesFlag(env: Env, db: Db, userId: string): Promise<true | Response> {
  const user = await db.users.findById(userId)
  if (!user) {
    return new Response(JSON.stringify({ error: "Forbidden" }), {
      status: 403,
      headers: { "Content-Type": "application/json" },
    })
  }

  const posthog = getOrCreatePostHogClient(env)
  const flags = await getAllFeatureFlags(posthog, userId, {
    github_login: user.github_login,
    discovery_enabled: !!user.discovery_enabled,
    is_admin: !!(user.is_admin ?? false),
    is_entirehq_member: false,
  })
  if (!flags[FLAG_DISPATCHES]) {
    return new Response(JSON.stringify({ error: "Not Found" }), {
      status: 404,
      headers: { "Content-Type": "application/json" },
    })
  }

  return true
}

function getDispatchScopeNotFoundError(body: CreateDispatchRequest): string {
  return normalizeScopeValues(body.org).length > 0
    ? "Organization not found"
    : "Repository not found"
}

dispatchRoutes.post("/users/me/dispatches", async (c) => {
  const userId = c.get("userId")
  const db = getDb(c.env)

  const flagGate = await requireDispatchesFlag(c.env, db, userId)
  if (flagGate !== true) {
    return flagGate
  }

  const body = await c.req.json<CreateDispatchRequest>().catch(() => null)
  const scopeRepos = body ? normalizeScopeValues(body.repo) : []
  const scopeOrgs = body ? normalizeScopeValues(body.org) : []
  if (
    !body ||
    (scopeRepos.length === 0 && scopeOrgs.length === 0) ||
    (scopeRepos.length > 0 && scopeOrgs.length > 0)
  ) {
    return c.json({ error: "Invalid dispatch request" }, 400)
  }

