    expect(res.status).toBe(200)
    const body = (await res.json()) as { userId: string; tokenScope: string }
    expect(body.userId).toBe("user-123")
    expect(body.tokenScope).toBe("trails:read")
  })

  it("returns 401 for missing Authorization header", async () => {
    const res = await makeRequest("/test")

    expect(res.status).toBe(401)
    const body = (await res.json()) as { error: string }
    expect(body.error).toBe("Not authenticated")
  })

  it("returns 401 for non-ent_ prefix token", async () => {
    const res = await makeRequest("/test", { Authorization: "Bearer ghp_some-github-token" })

    expect(res.status).toBe(401)
  })

  it("returns 401 for expired token", async () => {
    mockFindByTokenHash.mockResolvedValue({
      id: "token-id",
      user_id: "user-123",
      scope: "trails:read",
      expires_at: new Date(Date.now() - 86400000).toISOString(),
      last_used_at: null,
    })

    const res = await makeRequest("/test", { Authorization: "Bearer ent_expired-token" })

    expect(res.status).toBe(401)
    const body = (await res.json()) as { error: string }
    expect(body.error).toBe("Token expired")
  })

  it("returns 401 for token not found in DB", async () => {
    mockFindByTokenHash.mockResolvedValue(null)

    const res = await makeRequest("/test", { Authorization: "Bearer ent_unknown-token" })

    expect(res.status).toBe(401)
  })

  it("sets tokenScope on context", async () => {
    mockFindByTokenHash.mockResolvedValue({
      id: "token-id",
      user_id: "user-456",
      scope: "trails:write",
      expires_at: new Date(Date.now() + 86400000).toISOString(),
      last_used_at: null,
    })

    const res = await makeRequest("/test", { Authorization: "Bearer ent_scope-token" })

    expect(res.status).toBe(200)
    const body = (await res.json()) as { tokenScope: string }
    expect(body.tokenScope).toBe("trails:write")
  })

  it("calls updateLastUsedAt", async () => {
    mockFindByTokenHash.mockResolvedValue({
      id: "token-xyz",
