const TEST_ENCRYPTION_KEY = "REDACTED"

describe("parseTranscript", () => {
  it("parses simple user and assistant messages", () => {
    const jsonl = [
      JSON.stringify({
        type: "user",
        uuid: "user-1",
        timestamp: "2024-01-15T10:00:00Z",
        message: { content: "Hello, can you help me?" },
      }),
      JSON.stringify({
        type: "assistant",
        requestId: "req-1",
        timestamp: "2024-01-15T10:00:05Z",
        message: { id: "asst-1", content: "Of course! How can I assist you?" },
      }),
    ].join("\n")

    const result = parseTranscript(jsonl)

    expect(result).toHaveLength(2)
    expect(result[0]).toEqual({
      id: "user-1",
      role: "user",
      content: "Hello, can you help me?",
      timestamp: "2024-01-15T10:00:00Z",
    })
    expect(result[1]).toEqual({
      id: "asst-1",
      role: "assistant",
      content: "Of course! How can I assist you?",
      timestamp: "2024-01-15T10:00:05Z",
      toolCalls: [],
    })
  })

  it("handles content as array of blocks", () => {
    const jsonl = [
      JSON.stringify({
        type: "user",
        uuid: "user-1",
        timestamp: "2024-01-15T10:00:00Z",
        message: {
          content: [{ type: "text", text: "Please fix this bug" }],
        },
      }),
      JSON.stringify({
        type: "assistant",
        requestId: "req-1",
        timestamp: "2024-01-15T10:00:05Z",
        message: {
          id: "asst-1",
          content: [
            { type: "text", text: "I'll fix that for you. " },
            { type: "text", text: "Done!" },
          ],
        },
      }),
    ].join("\n")

    const result = parseTranscript(jsonl)

    expect(result).toHaveLength(2)
    expect(result[0].content).toBe("Please fix this bug")
    expect(result[1].content).toBe("I'll fix that for you. Done!")
  })

  it("filters out user messages that only contain tool results", () => {
    const jsonl = [
      JSON.stringify({
        type: "user",
        uuid: "user-1",
        timestamp: "2024-01-15T10:00:00Z",
        message: { content: "Run the tests" },
      }),
      JSON.stringify({
        type: "assistant",
        requestId: "req-1",
        timestamp: "2024-01-15T10:00:05Z",
        message: { id: "asst-1", content: "Running tests..." },
      }),
      JSON.stringify({
        type: "user",
        uuid: "user-2",
        timestamp: "2024-01-15T10:00:10Z",
        message: {
          content: [{ type: "tool_result", tool_use_id: "tool-1", content: "All tests passed" }],
        },
      }),
      JSON.stringify({
        type: "assistant",
        requestId: "req-2",
        timestamp: "2024-01-15T10:00:15Z",
        message: { id: "asst-2", content: "Tests completed successfully!" },
      }),
    ].join("\n")

    const result = parseTranscript(jsonl)

    // Tool-result-only user message is filtered out
    // All assistant messages with content are kept
    expect(result).toHaveLength(3)
    expect(result.map((m) => m.role)).toEqual(["user", "assistant", "assistant"])
    expect(result[0].content).toBe("Run the tests")
    expect(result[1].content).toBe("Running tests...")
    expect(result[2].content).toBe("Tests completed successfully!")
  })

  it("collapses streaming assistant updates by requestId", () => {
    const jsonl = [
      JSON.stringify({
        type: "user",
        uuid: "user-1",
        timestamp: "2024-01-15T10:00:00Z",
        message: { content: "Write a poem" },
      }),
      JSON.stringify({
