        timestamp: "2024-01-15T10:00:06Z",
        message: { id: "asst-1", content: "Roses are red" },
      }),
      JSON.stringify({
        type: "assistant",
        requestId: "req-1",
        timestamp: "2024-01-15T10:00:07Z",
        message: { id: "asst-1", content: "Roses are red, violets are blue" },
      }),
    ].join("\n")

    const result = parseTranscript(jsonl)

    expect(result).toHaveLength(2)
    expect(result[1].content).toBe("Roses are red, violets are blue")
  })

  it("keeps all assistant messages between user messages", () => {
    const jsonl = [
      JSON.stringify({
        type: "assistant",
        requestId: "req-0",
        timestamp: "2024-01-15T09:59:55Z",
        message: { id: "asst-0", content: "Welcome! How can I help?" },
