        timestamp: "2024-01-15T10:00:10Z",
        message: { id: "asst-2", content: "Intermediate response 2" },
      }),
      JSON.stringify({
        type: "assistant",
        requestId: "req-3",
        timestamp: "2024-01-15T10:00:15Z",
        message: { id: "asst-3", content: "Final response before next question" },
      }),
      JSON.stringify({
