function isCheckpointInWindow(checkpoint: CheckpointWithCommit, bounds: WindowBounds): boolean {
  const timestamp = checkpoint.created_at ?? checkpoint.commit_date
  if (!timestamp) return true

  const createdAt = new Date(timestamp).getTime()
  if (Number.isNaN(createdAt)) return true

  return createdAt >= bounds.sinceMs && createdAt <= bounds.untilMs
}

function parseStoredCheckpointAnalysis(
  analysisJson: string | null,
): StoredCheckpointAnalysis | null {
  if (!analysisJson) return null

  try {
    return JSON.parse(analysisJson) as StoredCheckpointAnalysis
  } catch {
    return null
  }
}

type ExtractionSection =
  | { type: "summary"; section: SummarySection }
  | { type: "investigation"; section: InvestigationSection }
  | { type: "decision"; section: DecisionSection }

function sectionSummary(entry: ExtractionSection): string | null {
  const { section } = entry
  const candidates: (string | undefined)[] = [section.narrative]
  if ("accepted" in section) candidates.push(section.accepted)
  if ("reasoning" in section) candidates.push(section.reasoning)
  if ("keyFindings" in section) candidates.push(section.keyFindings?.[0])
  candidates.push(section.title)

  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim()) {
      return candidate.trim()
    }
  }

  return null
}

function titleCaseSectionType(type: ExtractionSectionType): string {
  return type.charAt(0).toUpperCase() + type.slice(1)
}

function extractCheckpointSections(
  checkpoint: CheckpointWithCommit,
  analysis: AnalysisRow | undefined,
): {
  sections: DispatchSection[]
  usedCheckpoint: boolean
  warningCounts: Partial<DispatchWarnings>
} {
  const warningCounts: Partial<DispatchWarnings> = {}

  if (!analysis) {
    warningCounts.unknown_count = 1
  } else if (analysis.status === "pending" || analysis.status === "generating") {
    warningCounts.pending_count = 1
  } else if (analysis.status === "failed") {
    warningCounts.failed_count = 1
  }

  const parsedAnalysis =
    analysis?.status === "complete" ? parseStoredCheckpointAnalysis(analysis.analysis_json) : null
  const labels = parsedAnalysis?.extraction.labels ?? []
  const extractionSections: ExtractionSection[] = []
  if (parsedAnalysis?.extraction.summary) {
    extractionSections.push({ type: "summary", section: parsedAnalysis.extraction.summary })
  }
  if (parsedAnalysis?.extraction.investigation) {
    extractionSections.push({
      type: "investigation",
      section: parsedAnalysis.extraction.investigation,
    })
  }
  if (parsedAnalysis?.extraction.decision) {
    extractionSections.push({ type: "decision", section: parsedAnalysis.extraction.decision })
  }

  if (extractionSections.length > 0) {
    const sections = new Map<string, DispatchBullet[]>()

    for (const entry of extractionSections) {
      const text = sectionSummary(entry)
      if (!text) continue

      const label = titleCaseSectionType(entry.type)
      const bullet: DispatchBullet = {
        checkpoint_id: checkpoint.checkpoint_id,
        text,
        source: "cloud_analysis",
        branch: checkpoint.branch ?? "unknown",
        created_at: checkpoint.created_at ?? checkpoint.commit_date ?? new Date().toISOString(),
        labels,
      }
      const current = sections.get(label) ?? []
      current.push(bullet)
      sections.set(label, current)
    }

    if (sections.size > 0) {
      return {
        sections: [...sections.entries()].map(([label, bullets]) => ({ label, bullets })),
        usedCheckpoint: true,
        warningCounts,
      }
    }
  }

  const fallbackText = checkpoint.commit_message?.trim() || checkpoint.prompt?.trim()
  if (!fallbackText) {
    return {
      sections: [],
      usedCheckpoint: false,
      warningCounts: { ...warningCounts, uncategorized_count: 1 },
    }
  }

  return {
    sections: [
      {
        label: "Highlights",
        bullets: [
          {
            checkpoint_id: checkpoint.checkpoint_id,
            text: fallbackText,
            source: "commit_message",
            branch: checkpoint.branch ?? "unknown",
            created_at: checkpoint.created_at ?? checkpoint.commit_date ?? new Date().toISOString(),
            labels,
          },
        ],
      },
    ],
    usedCheckpoint: true,
    warningCounts,
  }
}

function mergeWarnings(target: DispatchWarnings, source: Partial<DispatchWarnings>): void {
  for (const key of Object.keys(source) as Array<keyof DispatchWarnings>) {
    target[key] += source[key] ?? 0
  }
}

// Escape markdown control characters in text sourced from checkpoints (commit
// messages, prompts, analysis narratives) so malicious content cannot inject
// links, images, or headings when the preview markdown is rendered. Also
// strip control characters so raw bytes can't break the bullet layout.
function escapeUntrustedMarkdown(text: string): string {
  return text
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, "")
    .replace(/([\\`*_{}\[\]()#+\-.!|~>])/g, "\\$1")
    .replace(/\r?\n/g, " ")
    .trim()
}

function buildGeneratedMarkdown(title: string, repos: DispatchRepoGroup[]): string {
  const lines: string[] = [`# ${escapeUntrustedMarkdown(title)}`]

  for (const repo of repos) {
    lines.push("", `## ${escapeUntrustedMarkdown(repo.full_name)}`)
    for (const section of repo.sections) {
      lines.push("", `### ${escapeUntrustedMarkdown(section.label)}`)
      for (const bullet of section.bullets) {
        lines.push(`- ${escapeUntrustedMarkdown(bullet.text)}`)
      }
    }
  }

  return lines.join("\n").trim()
}

function summarizeTitle(scopeRepos: string[], scopeOrgs: string[], repoCount: number): string {
  if (scopeRepos.length === 1) return `Dispatch for ${scopeRepos[0]}`
  if (scopeOrgs.length === 1) return `Dispatch for ${scopeOrgs[0]}`
  if (repoCount === 1) return "Dispatch"
  return `Dispatch across ${repoCount} repos`
}

function normalizeScopeValues(value: string | string[] | undefined): string[] {
  if (Array.isArray(value)) {
    return [...new Set(value.map((entry) => entry.trim()).filter(Boolean))]
  }

  if (typeof value === "string" && value.trim()) {
    return [value.trim()]
  }

  return []
}

function escapeDispatchPrompt(text: string): string {
  return escapePromptDelimiters(text).replace(
    /<\/?(?:dispatch_data|voice_preference)\b[^>]*>/gi,
    (match) => match.replace("<", "&lt;"),
  )
}

// Normalize user-supplied voice text before embedding it in the prompt:
// strip control chars + BiDi/zero-width overrides that could confuse the
// model, collapse internal whitespace runs, and trim. Length is bounded
// by MAX_DISPATCH_VOICE_LENGTH at the request boundary.
function sanitizeVoice(raw: string): string {
  return raw
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, "")
    .replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u2069]/g, "")
    .replace(/\s+/g, " ")
    .trim()
}

function buildDispatchGenerationUserPrompt(detail: DispatchDetail): string {
  const payload = {
    title: detail.title,
    covered_repos: detail.covered_repos,
    branches: detail.branches,
    voice: detail.voice ?? "neutral",
    window: detail.window,
    repos: detail.repos,
