async function validateSessionCsrf(
  c: Context<{ Bindings: Env; Variables: Variables }>,
  userId: string,
): Promise<Response | null> {
  const method = c.req.method
  if (method !== "POST" && method !== "PUT" && method !== "DELETE" && method !== "PATCH") {
