        .where("token_hash", "=", hash)
        .executeTakeFirst()
      if (!row) return null
      return {
        id: row.id,
        user_id: row.user_id,
        scope: row.scope,
        expires_at: row.expires_at.toISOString(),
        last_used_at: row.last_used_at?.toISOString() ?? null,
      }
    },

    async updateLastUsedAt(id: string) {
      assertValidUuid(id, "apiTokenId")
      await db
        .updateTable("api_tokens")
        .set({ last_used_at: new Date() })
        .where("id", "=", id)
        .execute()
    },

    async create(data) {
      const id = generateId()
      await db
        .insertInto("api_tokens")
        .values({
          id,
          user_id: data.userId,
          token_hash: data.tokenHash,
          name: data.name,
          scope: data.scope,
          expires_at: new Date(data.expiresAt),
        })
        .execute()
      const row = await db
        .selectFrom("api_tokens")
        .select(["id", "user_id", "name", "scope", "expires_at", "last_used_at", "created_at"])
        .where("id", "=", id)
        .executeTakeFirstOrThrow()
      return rowToApiToken(row)
    },

    async listForUser(userId: string) {
      assertValidUuid(userId, "userId")
      const rows = await db
        .selectFrom("api_tokens")
        .select(["id", "user_id", "name", "scope", "expires_at", "last_used_at", "created_at"])
        .where("user_id", "=", userId)
        .where("expires_at", ">", new Date())
        .orderBy("created_at", "desc")
        .execute()
      return rows.map(rowToApiToken)
    },

    async deleteById(id: string, userId: string) {
      assertValidUuid(id, "apiTokenId")
      assertValidUuid(userId, "userId")
      const result = await db
        .deleteFrom("api_tokens")
        .where("id", "=", id)
        .where("user_id", "=", userId)
        .executeTakeFirst()
      return BigInt(result.numDeletedRows) > 0n
    },
  }
}

