// Cloudflare Workers environment bindings

/**
 * Type utility to extract required (non-optional) keys from a type.
 */
type RequiredKeys<T> = {
  [K in keyof T]-?: undefined extends T[K] ? never : K
}[keyof T]

/**
 * All required (non-optional) keys from the Env interface.
 */
type RequiredEnvKey = RequiredKeys<Env>

/**
 * List of required environment variables validated at runtime by validateEnv().
 *
 * TypeScript helps keep this list in sync with the Env interface:
 * - `satisfies readonly RequiredEnvKey[]` ensures each entry is a valid required key
 * - The compile-time assertion below errors if any required Env key is missing
 *
 * However, the actual validation happens at runtime since TypeScript types are
 * erased. The validateEnv() function checks that these values are present and
 * non-empty when the worker handles its first request.
 */
const REQUIRED_ENV_VARS = [
  "ENCRYPTION_KEY",
  "ENTIRE_CACHE",
  "ENVIRONMENT",
  "FRONTEND_BASE_URL",
  "GITHUB_APP_NAME",
  "GITHUB_APP_PRIVATE_KEY",
  "GITHUB_CLIENT_ID",
  "GITHUB_CLIENT_SECRET",
  "GITHUB_WEBHOOK_SECRET",
  "AGENT_RUN_QUEUE",
  "HYPERDRIVE",
  "HYPERDRIVE_BACKGROUND",
  "REPO_SYNC_QUEUE",
  "SESSION_SECRET",
  "USER_REPO_SYNC_QUEUE",
  "WEBHOOK_QUEUE",
] as const satisfies readonly RequiredEnvKey[]

// Compile-time check: fails to build if any required Env key is missing from the array above
type _MissingKeys = Exclude<RequiredEnvKey, (typeof REQUIRED_ENV_VARS)[number]>
type _AssertComplete = [_MissingKeys] extends [never] ? true : never
const _assertAllKeysIncluded: _AssertComplete = true

let validated = false

/**
 * Validate that all required environment variables are present and non-empty.
 * Throws an error with a clear message listing any missing variables.
 * Only runs once per worker instance.
 */
export function validateEnv(env: Env): void {
  if (validated) return

  const missing: string[] = []

  for (const key of REQUIRED_ENV_VARS) {
    const value = env[key]
    if (value === undefined || value === null || value === "") {
      missing.push(key)
    }
  }

  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(", ")}`)
  }

  validated = true
}

/**
 * Check if running in local development mode.
 */
export function isLocalDev(env: { ENVIRONMENT: string }): boolean {
  return env.ENVIRONMENT === "development"
}

/**
 * Check if a user should be treated as admin.
 */
export function isAdmin(_env: { ENVIRONMENT: string }, dbIsAdmin: boolean | number): boolean {
  return dbIsAdmin === true || dbIsAdmin === 1
}

export interface Env {
  // PlanetScale MySQL via Hyperdrive
  HYPERDRIVE: Hyperdrive
  // Separate Hyperdrive pool for background work (queues, crons)
  HYPERDRIVE_BACKGROUND: Hyperdrive

  // KV Namespace for caching
  ENTIRE_CACHE: KVNamespace

  // Cloudflare Queues
  WEBHOOK_QUEUE: Queue // Webhook retry queue
  AGENT_RUN_QUEUE: Queue // Agent run queue
  REPO_SYNC_QUEUE: Queue // Repo checkpoint sync queue
  USER_REPO_SYNC_QUEUE: Queue // User repo sync queue (for stale/failed syncs)
  SANDBOX_RUN_QUEUE?: Queue // Sandbox run prompt execution queue
  SANDBOX_SNAPSHOT_QUEUE?: Queue // Sandbox snapshot build queue
  // Environment variables
  ENVIRONMENT: string // e.g., "development", "staging", "production"
  FRONTEND_BASE_URL: string // Used for redirects/CORS
  API_BASE_URL?: string // If set, used for OAuth redirect URIs; defaults to request origin

  // Secrets (set via wrangler secret put)
  GITHUB_CLIENT_ID: string
  GITHUB_CLIENT_SECRET: string
  GITHUB_APP_NAME: string // GitHub App slug (e.g., "my-app-name")
  GITHUB_APP_PRIVATE_KEY: string // GitHub App private key (PEM format)
  ENCRYPTION_KEY: string
  SESSION_SECRET: string
  GITHUB_WEBHOOK_SECRET: string

  // Darwin backend (optional, experimental)
  DARWIN_BASE_URL?: string // e.g., https://localhost:8080
  ENTIRE_WEB_API_TOKEN?: string // API token for Darwin backend

  // E2B Sandbox
  E2B_MOCK?: string

  // E2B Sandbox credentials
  E2B_API_KEY?: string // E2B API key (e.g. "e2b_...")
  ANTHROPIC_API_KEY?: string // Passed to the agent CLI inside the sandbox
  // Dedicated key for the checkpoint analysis pipeline so trail runs and
  // analysis don't share a bucket.
  ANTHROPIC_API_KEY_ANALYSIS?: string
  // Dedicated key for the dispatch generation path so its spend is isolated
  // from trail runs and analysis.
  ANTHROPIC_API_KEY_DISPATCHES?: string
  CURSOR_API_KEY?: string // Passed to Cursor agent runs inside the sandbox
  SANDBOX_PROVIDER?: string // Active sandbox provider for /runs (for example "daytona")
  DAYTONA_API_KEY?: string // Daytona API key
  DAYTONA_API_URL?: string // Daytona API URL override
  DAYTONA_TARGET?: string // Daytona target/region
  DAYTONA_SNAPSHOT?: string // Base Daytona snapshot name
  DAYTONA_AGENT_PORT?: string // sandbox-agent port
  DAYTONA_PREVIEW_TTL_SECONDS?: string
  DAYTONA_AUTO_STOP_MINUTES?: string

  // Modal Sandbox credentials
  MODAL_TOKEN_ID?: string
  MODAL_TOKEN_SECRET?: string
  MODAL_APP_NAME?: string
  MODAL_BASE_IMAGE?: string
  MODAL_AUTO_STOP_MINUTES?: string
  MODAL_PROXY_URL?: string
  MODAL_PROXY_KEY?: string
  MODAL_PROXY_SECRET?: string
  MODAL_ENABLE_MEMORY_SNAPSHOTS?: string

  // Search (optional — search endpoint returns 503 if missing)
  TURBOPUFFER_API_KEY?: string
  OPENAI_API_KEY?: string
  COHERE_API_KEY?: string

  // Search index queue (optional — indexing skipped if not configured)
  SEARCH_INDEX_QUEUE?: Queue

  // Analysis generation queue (optional — proactive analysis generation skipped if not configured)
  ANALYSIS_QUEUE?: Queue

  // Durable Object namespace for the global Anthropic rate limiter (optional —
  // falls back to an unwrapped client when not configured, e.g. local dev)
  ANTHROPIC_RATE_LIMITER?: DurableObjectNamespace<
    import("./lib/anthropic-rate-limiter-do").AnthropicRateLimiter
  >
  // Rate limiter budget overrides (optional — safe defaults applied in the DO)
  ANTHROPIC_RPM_LIMIT?: string
  ANTHROPIC_TPM_LIMIT?: string

  // PostHog feature flags (optional — controls org-level gating for semantic search)
  POSTHOG_API_KEY?: string
  POSTHOG_PERSONAL_API_KEY?: string

  // OpenTelemetry (optional)
  OTEL_EXPORTER_OTLP_ENDPOINT?: string // e.g., https://api.honeycomb.io
  OTEL_EXPORTER_OTLP_HEADERS?: string // e.g., x-honeycomb-team=your-api-key

  // Dev-only: skip GitHub OAuth, use a fake dev session (requires ENVIRONMENT=development)
  BYPASS_GH_OAUTH?: string
}

// Variables stored in Hono context
export interface Variables {
  userId: string
  tokenScope?: string
  authTimestamp?: number
  // Repository access record, populated by route middleware that has already
  // resolved and authorized repo access (e.g. requireTrailsAdmin). Route
  // handlers can reuse this to avoid duplicate DB lookups.
  repoAccess?: import("./lib/db/repos").Repo
}

// Hono context with bindings
import type { Context } from "hono"

export type AppContext = Context<{ Bindings: Env; Variables: Variables }>

