import { Hono } from "hono"
import { describe, it, expect, vi, beforeEach } from "vitest"

import type { Env, Variables } from "../env"
import { requireAuth, optionalAuth, requireSessionOrBearerAuth } from "./middleware"

const mockFindByTokenHash = vi.fn()
const mockUpdateLastUsedAt = vi.fn()

function createMockKV() {
  const store = new Map<string, string>()
  return {
    get: vi.fn(async (key: string, format?: string) => {
      const val = store.get(key) ?? null
      if (val && format === "json") return JSON.parse(val)
      return val
    }),
    put: vi.fn(async (key: string, value: string) => {
      store.set(key, value)
    }),
    delete: vi.fn(async (key: string) => {
      store.delete(key)
    }),
    _store: store,
  }
}

const mockGetSession = vi.fn()
vi.mock("./session", () => ({
  getSession: (...args: unknown[]) => mockGetSession(...args),
}))

vi.mock("./db", () => ({
  getDb: () => ({
    apiTokens: {
      findByTokenHash: (...args: unknown[]) => mockFindByTokenHash(...args),
      updateLastUsedAt: (...args: unknown[]) => mockUpdateLastUsedAt(...args),
    },
  }),
}))

vi.mock("./crypto", async (importOriginal) => {
  const actual = await importOriginal<typeof import("./crypto")>()
  return {
    ...actual,
    sha256Hex: vi.fn(async (input: string) => `hash_of_${input}`),
  }
})

function createTestApp(
  mockKV: ReturnType<typeof createMockKV>,
  middleware: typeof requireAuth | typeof optionalAuth | typeof requireSessionOrBearerAuth,
) {
  const app = new Hono<{ Bindings: Env; Variables: Variables }>()

  app.use("*", async (c, next) => {
    c.env = {
      ENTIRE_CACHE: mockKV as unknown as KVNamespace,
      FRONTEND_BASE_URL: "http://localhost:5173",
    } as Env
    await next()
  })

  app.use("*", middleware)

  app.get("/test", (c) => {
    const userId = c.get("userId")
    return c.json({ userId: userId ?? null })
  })

  app.post("/test", (c) => {
    const userId = c.get("userId")
    return c.json({ userId: userId ?? null })
  })

  return app
}

describe("middleware", () => {
  let mockKV: ReturnType<typeof createMockKV>

  beforeEach(() => {
    mockKV = createMockKV()
    vi.clearAllMocks()
    mockGetSession.mockResolvedValue(null)
    mockFindByTokenHash.mockResolvedValue(null)
    mockUpdateLastUsedAt.mockResolvedValue(undefined)
  })

  describe("requireAuth", () => {
    it("authenticates via session cookie", async () => {
      mockGetSession.mockResolvedValue({
        userId: "session-user",
        expiresAt: Date.now() + 86400000,
      })

      const app = createTestApp(mockKV, requireAuth)
      const res = await app.request("/test", {
        headers: { Cookie: "session=valid-session-token" },
      })

      expect(res.status).toBe(200)
      const body = (await res.json()) as { userId: string }
      expect(body.userId).toBe("session-user")
    })

    it("does not accept Bearer tokens by default", async () => {
      const app = createTestApp(mockKV, requireAuth)
      const res = await app.request("/test", {
        headers: { Authorization: "Bearer test-token" },
      })

      expect(res.status).toBe(401)
    })
  })

  describe("optionalAuth", () => {
    it("uses session auth when available", async () => {
      mockGetSession.mockResolvedValue({
        userId: "cookie-user",
        expiresAt: Date.now() + 86400000,
      })

      const app = createTestApp(mockKV, optionalAuth)
      const res = await app.request("/test", {
        headers: { Cookie: "session=valid-token" },
      })

      expect(res.status).toBe(200)
      const body = (await res.json()) as { userId: string }
      expect(body.userId).toBe("cookie-user")
    })

    it("ignores Bearer tokens by default", async () => {
      const app = createTestApp(mockKV, optionalAuth)
      const res = await app.request("/test", {
        headers: { Authorization: "Bearer test-token" },
      })

      expect(res.status).toBe(200)
      const body = (await res.json()) as { userId: string | null }
      expect(body.userId).toBeNull()
    })
  })

  describe("requireSessionOrBearerAuth", () => {
    it("authenticates via session cookie", async () => {
      mockGetSession.mockResolvedValue({
        userId: "session-user",
        expiresAt: Date.now() + 86400000,
      })

      const app = createTestApp(mockKV, requireSessionOrBearerAuth)
      const res = await app.request("/test", {
        headers: { Cookie: "session=valid-session-token" },
      })

      expect(res.status).toBe(200)
      const body = (await res.json()) as { userId: string }
      expect(body.userId).toBe("session-user")
    })

    it("authenticates via ent_ bearer token when no session cookie is present", async () => {
      mockFindByTokenHash.mockResolvedValue({
        id: "token-id",
        user_id: "bearer-user",
        scope: "dispatches:read",
        expires_at: new Date(Date.now() + 86400000).toISOString(),
        last_used_at: null,
      })

      const app = createTestApp(mockKV, requireSessionOrBearerAuth)
      const res = await app.request("/test", {
        headers: { Authorization: "Bearer ent_test-token" },
      })

      expect(res.status).toBe(200)
      const body = (await res.json()) as { userId: string }
      expect(body.userId).toBe("bearer-user")
    })

    it("falls back to bearer auth when a session cookie is present but expired", async () => {
      mockGetSession.mockResolvedValue(null)
      mockFindByTokenHash.mockResolvedValue({
        id: "token-id",
        user_id: "bearer-user",
        scope: "dispatches:read",
        expires_at: new Date(Date.now() + 86400000).toISOString(),
        last_used_at: null,
      })

      const app = createTestApp(mockKV, requireSessionOrBearerAuth)
      const res = await app.request("/test", {
        headers: {
          Cookie: "session=expired-session-token",
          Authorization: "Bearer ent_test-token",
        },
      })

      expect(res.status).toBe(200)
      const body = (await res.json()) as { userId: string }
      expect(body.userId).toBe("bearer-user")
    })
  })
})

