	if len(got) != len(ids) {
		t.Fatalf("expected %d analyses, got %d", len(ids), len(got))
	}
	if got["cp-200"].Summary != "summary cp-200" {
		t.Fatalf("unexpected analysis payload: %+v", got["cp-200"])
	}
}

