	t.Parallel()

	oldRunDispatch := runDispatch
	oldRenderDispatch := renderDispatch
	runDispatch = func(_ context.Context, opts dispatchpkg.Options) (*dispatchpkg.Dispatch, error) {
		if !opts.Generate {
			t.Fatal("expected generate flag to propagate")
		}
		return &dispatchpkg.Dispatch{
			Generated:     true,
			GeneratedText: "generated dispatch",
		}, nil
	}
	renderDispatch = func(_ string, dispatch *dispatchpkg.Dispatch) (string, error) {
		if dispatch.GeneratedText != "generated dispatch" {
			t.Fatalf("unexpected dispatch: %+v", dispatch)
		}
		return "generated dispatch\n", nil
	}
	t.Cleanup(func() {
		runDispatch = oldRunDispatch
		renderDispatch = oldRenderDispatch
	})

	cmd := newDispatchCmd()
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.SetOut(&stdout)
	cmd.SetErr(&stderr)
	cmd.SetArgs([]string{"--generate", "--repos", "entireio/cli"})
	cmd.SetContext(context.Background())

	if err := cmd.Execute(); err != nil {
