	}
	if got := stdout.String(); got != "generated dispatch\n" {
		t.Fatalf("unexpected stdout: %q", got)
	}
	if got := stderr.String(); got != "Generating dispatch...\n" {
		t.Fatalf("unexpected stderr: %q", got)
	}
}

