176	func (m dispatchStatusModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
177		switch msg := msg.(type) {
178		case tea.WindowSizeMsg:
179			m.width = msg.Width
180			m.height = msg.Height
181			return m, nil
182		case spinner.TickMsg:
183			var cmd tea.Cmd
184			m.spinner, cmd = m.spinner.Update(msg)
185			return m, cmd
186		case dispatchRenderResult:
187			m.result = msg
188			return m, tea.Quit
189		case tea.KeyMsg:
190			switch msg.String() {
191			case "ctrl+c", "esc", "q":
192				if m.cancel != nil {
193					m.cancel()
194				}
195				m.result.err = errDispatchCancelled
196				return m, tea.Quit
197			}
198		}
