		}
		if body["repo"] == nil {
			t.Fatalf("bad body: %v", body)
		}
		repo, ok := body["repo"].(string)
		if !ok || repo != "entireio/cli" {
			t.Fatalf("bad repo payload: %v", body["repo"])
		}
		if _, ok := body["repos"]; ok {
			t.Fatalf("did not expect repos in request body: %v", body)
