dispatchRoutes.post("/dispatches", async (c) => {
  const userId = c.get("userId")
  const db = getDb(c.env)

  const flagGate = await requireDispatchesFlag(c.env, db, userId)
  if (flagGate !== true) {
    return flagGate
  }

  const body = await c.req.json<CreateDispatchRequest>().catch(() => null)
  const scopeRepos = body ? normalizeScopeValues(body.repo) : []
  const scopeOrgs = body ? normalizeScopeValues(body.org) : []
  if (
    !body ||
    (scopeRepos.length === 0 && scopeOrgs.length === 0) ||
    (scopeRepos.length > 0 && scopeOrgs.length > 0)
  ) {
    return c.json({ error: "Invalid dispatch request" }, 400)
  }

  if (typeof body.voice === "string" && body.voice.length > MAX_DISPATCH_VOICE_LENGTH) {
    return c.json({ error: "Voice is too long" }, 400)
  }

  if (scopeRepos.length > 0) {
    const repoAccessResults = await Promise.all(
      scopeRepos.map((repo) => checkRepoAccess(db, repo, userId, { requireRepo: true })),
    )
    for (const repoAccess of repoAccessResults) {
      if (repoAccess instanceof Response) {
        return repoAccess
      }
    }
  }

  const record = await buildDispatchRecord(db, userId, body)
  if (!record) {
    return c.json({ error: getDispatchScopeNotFoundError(body) }, 404)
  }

  try {
    const generatedMarkdown = await generateDispatchMarkdown(c.env, record)
    return c.json(
      buildDispatchResponse({
        ...record,
        generated_markdown: generatedMarkdown,
      }),
    )
  } catch (error) {
    console.error("dispatch generation failed", error)
    return c.json({ error: "Dispatch generation unavailable" }, 503)
  }
})

dispatchRoutes.post("/dispatches/checkpoint-analyses/batch", async (c) => {
  const userId = c.get("userId")
  const db = getDb(c.env)

  const body = await c.req
    .json<{ checkpointIds?: string[]; repoFullName?: string }>()
    .catch(() => null)
  const checkpointIds = body?.checkpointIds
  const repoFullName = body?.repoFullName

  if (!repoFullName || typeof repoFullName !== "string") {
    return c.json({ error: "repoFullName is required" }, 400)
  }
  if (!Array.isArray(checkpointIds) || checkpointIds.length === 0) {
    return c.json({ error: "checkpointIds must be a non-empty array" }, 400)
  }
  if (checkpointIds.length > 200) {
    return c.json({ error: "Maximum 200 checkpoint IDs per request" }, 400)
  }

  const invalidId = checkpointIds.find((id) => !isValidCheckpointId(id))
  if (invalidId) {
    return c.json({ error: `Invalid checkpoint ID format: ${invalidId}` }, 400)
  }

  const [repoAccess, flagResult] = await Promise.all([
    checkRepoAccess(db, repoFullName, userId, { requireRepo: true }),
    requireAnalysisFlag(c.env, db, userId),
  ])
  if (repoAccess instanceof Response) return repoAccess
  if (flagResult instanceof Response) return flagResult

  const analyses = await db.analyses.getByCheckpointIds(repoAccess.id, checkpointIds)
  const analysisMap = new Map(analyses.map((a) => [a.checkpoint_id, a]))

  const analysesByCheckpoint: Record<string, Record<string, unknown>> = {}
  for (const checkpointId of checkpointIds) {
    analysesByCheckpoint[checkpointId] = formatCheckpointAnalysisResponse(
      analysisMap.get(checkpointId) ?? null,
    )
  }

  return c.json({ analyses: analysesByCheckpoint })
})

