        return result.checkpoints.map((checkpoint) => ({
          id: checkpoint.checkpoint_id,
          repo_full_name: repo.full_name,
          branch: checkpoint.branch ?? "unknown",
          created_at: checkpoint.created_at ?? checkpoint.commit_date ?? new Date(0).toISOString(),
        }))

