dispatchRoutes.get("/dispatches/orgs/:org/checkpoints", async (c) => {
  const userId = c.get("userId")
  const org = c.req.param("org")
  const sinceParam = c.req.query("since")
  const limitParam = c.req.query("limit")
  const cursorParam = c.req.query("cursor")

  if (!sinceParam) {
    return c.json({ error: "since is required" }, 400)
  }

  const since = new Date(sinceParam)
  if (Number.isNaN(since.getTime())) {
    return c.json({ error: "Invalid since value" }, 400)
  }

  let limit = DISPATCH_ORG_CHECKPOINTS_DEFAULT_LIMIT
  if (limitParam) {
    const parsedLimit = Number.parseInt(limitParam, 10)
    if (Number.isNaN(parsedLimit) || parsedLimit <= 0) {
      return c.json({ error: "Invalid limit value" }, 400)
    }
    limit = Math.min(parsedLimit, DISPATCH_ORG_CHECKPOINTS_MAX_LIMIT)
  }

  let offset = 0
  if (cursorParam) {
    const parsedCursor = Number.parseInt(cursorParam, 10)
    if (Number.isNaN(parsedCursor) || parsedCursor < 0) {
      return c.json({ error: "Invalid cursor value" }, 400)
    }
    offset = parsedCursor
  }

  const db = getDb(c.env)
  const accessibleRepos = (await db.repos.getAccessibleByUser(userId)).filter((repo) =>
    repo.full_name.startsWith(`${org}/`),
  )

  const checkpointPages = await Promise.all(
    accessibleRepos.map(async (repo) => {
      const branches = await db.checkpoints.getBranchesWithCheckpoints(repo.id)
      const branchNames = [...new Set(branches.map((branch) => branch.branch).filter(Boolean))]

      const branchResults = await Promise.all(
        branchNames.map((branch) =>
          db.checkpoints.getRepoWithCheckpoints(repo.full_name, userId, branch, DISPATCH_PER_BRANCH_LIMIT),
        ),
      )

      return branchResults.flatMap((result) => {
        if (!result || result === "no_access") {
          return []
        }

        return result.checkpoints.map((checkpoint) => ({
          id: checkpoint.checkpoint_id,
          repo_full_name: repo.full_name,
          branch: checkpoint.branch ?? "unknown",
          created_at: checkpoint.created_at ?? checkpoint.commit_date ?? new Date(0).toISOString(),
        }))
      })
    }),
  )

  const filtered = checkpointPages
    .flat()
    .filter((checkpoint) => new Date(checkpoint.created_at).getTime() >= since.getTime())
    .sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime())

  const page = filtered.slice(offset, offset + limit)
  const nextCursor = offset + limit < filtered.length ? String(offset + limit) : null

  return c.json({
    checkpoints: page,
    cursor: nextCursor,
  })
})

