import type { AnalysisRow, Db } from "../lib/db/db-types"
import { createAuthenticatedRateLimit, requireSessionOrBearerAuth } from "../lib/middleware"
import { getAllFeatureFlags, getOrCreatePostHogClient } from "../lib/posthog"
import type {
  DecisionSection,
  ExtractionSectionType,
  InvestigationSection,
  StoredCheckpointAnalysis,
  SummarySection,
} from "../types"
import { checkRepoAccess } from "./cache"

type DispatchBranches = string[] | "all"

interface DispatchWindow {
  normalized_since: string
  normalized_until: string
  first_checkpoint_created_at: string | null
  last_checkpoint_created_at: string | null
}

interface DispatchTotals {
  checkpoints: number
  used_checkpoint_count: number
  branches: number
  files_touched: number
}

interface DispatchWarnings {
  access_denied_count: number
  pending_count: number
  failed_count: number
  unknown_count: number
  uncategorized_count: number
  truncated_count: number
}

interface DispatchBullet {
  checkpoint_id: string
  text: string
  source: "cloud_analysis" | "local_summary" | "commit_message"
  branch: string
  created_at: string
  labels: string[]
}

interface DispatchSection {
