// Transcript rendering, message analysis, and patch/diff processing utilities
// for the checkpoint analysis pipeline.

import type { SessionTranscript, ToolCall, ToolCallResult, TranscriptMessage } from "../types"
import type { CheckpointAnalysisUnit } from "./checkpoint-analysis-pipeline"

const EDIT_TOOL_NAMES = new Set(["Edit", "NotebookEdit", "apply_patch"])

// ---------------------------------------------------------------------------
// Utilities
// ---------------------------------------------------------------------------

export function estimateTokens(text: string): number {
  return Math.ceil(text.length / 4)
}

function getMessageRecord(message: TranscriptMessage): Record<string, unknown> {
  return message as unknown as Record<string, unknown>
}

function truncateInline(text: string, maxLength = 120): string {
  const normalized = text.replace(/\s+/g, " ").trim()
  if (normalized.length <= maxLength) return normalized
  return `${normalized.slice(0, maxLength - 1)}…`
}

export function escapePromptDelimiters(text: string): string {
  return text.replace(
    /<\/?(?:previous_context|transcript|transcript_tail|extraction)\b[^>]*>/gi,
    (match) => match.replace("<", "&lt;"),
  )
}

// ---------------------------------------------------------------------------
// Tool call / message summarization
// ---------------------------------------------------------------------------

function summarizeEditReference(toolCall: ToolCall): string {
  if (!EDIT_TOOL_NAMES.has(toolCall.name)) return ""

  const filePath =
    (toolCall.input.file_path as string | undefined) ?? (toolCall.input.path as string | undefined)

  if (
    (toolCall.name === "Edit" || toolCall.name === "NotebookEdit") &&
    typeof toolCall.input.old_string === "string" &&
    typeof toolCall.input.new_string === "string"
  ) {
    return `editRef=${toolCall.id} file=${filePath ?? "unknown"} before=${truncateInline(
      toolCall.input.old_string,
    )} after=${truncateInline(toolCall.input.new_string)}`
  }

  if (toolCall.name === "apply_patch" && typeof toolCall.input.patch === "string") {
    return `editRef=${toolCall.id} patch=${truncateInline(toolCall.input.patch, 240)}`
  }

  return `editRef=${toolCall.id}${filePath ? ` file=${filePath}` : ""}`
}

function summarizeToolCall(toolCall: ToolCall): string {
  const arg =
    (toolCall.input.file_path as string | undefined) ??
    (toolCall.input.path as string | undefined) ??
    (toolCall.input.command as string | undefined) ??
    (toolCall.input.pattern as string | undefined) ??
    ""
  const toolSummary = arg ? `${toolCall.name}(${String(arg).slice(0, 80)})` : toolCall.name
  const editSummary = summarizeEditReference(toolCall)
  const resultSummary = summarizeToolResult(toolCall.result)

  if (!editSummary) {
    return resultSummary ? `${toolSummary} [Result: ${resultSummary}]` : toolSummary
  }

  const details = [editSummary, resultSummary ? `Result: ${resultSummary}` : ""]
    .filter(Boolean)
    .join("; ")
  return `${toolSummary} [${details}]`
}

function summarizeToolResult(result: ToolCallResult | undefined): string {
  if (result === undefined) return ""

  if (result.type === "error") {
    return result.error ? `error: ${result.error.slice(0, 80)}` : "error"
  }

  if (result.output) {
    return `output: ${result.output.slice(0, 80)}`
  }

  if (result.file?.filePath) {
    const fileSummary = `file: ${result.file.filePath.slice(0, 80)}`
    return result.file.numLines !== undefined
      ? `${fileSummary}, lines: ${result.file.numLines}`
      : fileSummary
  }

  if (result.matchCount !== undefined) {
    return `matches: ${result.matchCount}`
  }

  if (result.answers && Object.keys(result.answers).length > 0) {
    return `answers: ${Object.entries(result.answers)
      .map(([key, value]) => `${key}=${value}`)
      .join(", ")
      .slice(0, 80)}`
  }

  return result.type
}

function summarizeStandaloneToolResult(message: TranscriptMessage): string {
  const parsed = getMessageRecord(message)
  const toolUseResult = parsed.toolUseResult
  if (toolUseResult === undefined || typeof toolUseResult !== "object" || toolUseResult === null) {
    return ""
  }

  const raw = toolUseResult as Record<string, unknown>
  const normalized: ToolCallResult = {
    type: raw.type === "error" ? "error" : "text",
  }

  if (raw.file && typeof raw.file === "object" && raw.file !== null) {
    const file = raw.file as Record<string, unknown>
    if (typeof file.filePath === "string") {
      normalized.file = {
        filePath: file.filePath,
        numLines: typeof file.numLines === "number" ? file.numLines : undefined,
      }
    }
  }

  if (typeof raw.error === "string") {
    normalized.error = raw.error
    normalized.type = "error"
  }

  if (raw.answers && typeof raw.answers === "object" && raw.answers !== null) {
    normalized.answers = Object.fromEntries(
      Object.entries(raw.answers as Record<string, unknown>).filter(
        (entry): entry is [string, string] => typeof entry[1] === "string",
      ),
    )
  }

  return summarizeToolResult(normalized)
}

// ---------------------------------------------------------------------------
// Message rendering
// ---------------------------------------------------------------------------

export function renderMessage(message: TranscriptMessage): string {
  const standaloneToolResultSummary = summarizeStandaloneToolResult(message)
  const toolSuffix =
    message.toolCalls && message.toolCalls.length > 0
      ? `\nTools: ${message.toolCalls.map(summarizeToolCall).join(", ")}`
      : ""
  const toolResultSuffix = standaloneToolResultSummary
    ? `\nTool result: ${standaloneToolResultSummary}`
    : ""
  return `[${message.role}] ${message.content}${toolSuffix}${toolResultSuffix}`
}

export function renderSession(session: SessionTranscript): string {
  const header = `--- Session ${session.sessionId} (${session.agent}) ---`
  return [header, ...session.messages.map(renderMessage)].join("\n")
}

export function renderChunkUnit(unit: CheckpointAnalysisUnit): string {
  return unit.messages.map(renderMessage).join("\n")
}

function summarizeOriginatingToolCalls(unit: CheckpointAnalysisUnit, messageIndex: number): string {
  const toolCalls = new Map<string, ToolCall>()

  for (let index = 0; index < messageIndex; index++) {
    const message = unit.messages[index]
    if (!message?.toolCalls) continue

    for (const toolCall of message.toolCalls) {
      if (!toolCalls.has(toolCall.id)) toolCalls.set(toolCall.id, toolCall)
    }
  }

  return Array.from(toolCalls.values()).map(summarizeToolCall).join(", ")
}

export function renderOversizedFallbackMessage(
  unit: CheckpointAnalysisUnit,
  messageIndex: number,
): string {
  const message = unit.messages[messageIndex]
  if (message === undefined) return ""

  const toolContext = isToolResultOnlyMessage(message)
    ? summarizeOriginatingToolCalls(unit, messageIndex)
    : ""

  const contextPrefix = toolContext ? `Tool context: ${toolContext}\n` : ""
  return `${contextPrefix}${renderMessage(message)}`
}

// ---------------------------------------------------------------------------
// Message analysis
// ---------------------------------------------------------------------------

export function isToolResultOnlyMessage(message: TranscriptMessage): boolean {
  if (message.role !== "user") return false

  const parsed = getMessageRecord(message)
  const content = parsed.content
  const toolUseResult = parsed.toolUseResult

  if (toolUseResult !== undefined) {
    return typeof content !== "string" || content.trim().length === 0
  }

