		return "marvin"
	case "custom":
		if value := strings.TrimSpace(s.voiceCustom); value != "" {
			return value
		}
	}
	return "neutral"
}

func (s dispatchWizardState) showCustomVoiceInput() bool {
	return strings.TrimSpace(s.voicePreset) == "custom"
}

